discrete DataCollectionAndPreprocessingSystem
port:
    event input real SignalA;
    event output real SendData;
state:
    initial state Initial
        when entry() then
            statehold(1);
        end;
        when receive(SignalA) then
            transition(DataCollection);
        end;
    end;

    state DataCollection
        when entry() then
            statehold(1);
        end;
        when ConditionB then
            transition(DataPreprocessing);
        end;
    end;

    state DataPreprocessing
        when entry() then
            statehold(1);
        end;
        when ConditionC then
            transition(SendDataState);
        end;
    end;

    state SendDataState
        when entry() then
            statehold(1);
        end;
        when timeover() then
            transition(Initial);
            out
                send(SendData, 1);
        end;
    end;
end;
end;

